            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
# POST /api/sheets/{sheetId}/people/{personId}/retire — retire a person from a date (blank: the
# sheet's today); a date that is not a date is refused. Their claims keep counting in every total.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# GET /api/sheets/{sheetId}/people — the people on the sheet, in the order they were added.
list:
  class: net.officefloor.hq.app.person.ListPeople
  govern: [ readonly-transaction ]
-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several over time. Only a person's OPEN claims dated within a hold count in no live total;
-- a claim bound by a statement still counts whatever its date. A person held before holds were
-- dated keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    from_date DATE         NOT NULL,
    to_date   DATE,
    held_by   VARCHAR(200) NOT NULL,
    held_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_hold_person ON person_hold (sheet_id, person_id, id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by)
    SELECT sheet_id, id, DATE '0001-01-01', NULL, created_by FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;

